def _with(patches, fn):
    for p in patches:
        p.start()
    try:
        return fn()
    finally:
        for p in patches:
            p.stop()


class TestTickHops:
    def test_io_off_tk_thread_and_results_applied_in_order(self, tmp_path):
        c, entry, refreshes = _controller(tmp_path)
        io_threads: list = []

        def git_check(cwd, trunk_ref, branch):
            io_threads.append(threading.current_thread())
            return (GitStatus.UNSTAGED_CHANGES, False)

        next_ms = _with(_patches(cwd=str(tmp_path), git_check=git_check), lambda: _run_tick(c))

        assert io_threads and threading.main_thread() not in io_threads
        assert entry.branch == "feat"
        assert entry.git_status == GitStatus.UNSTAGED_CHANGES
        assert entry.state == StatusState.WORKING
        assert entry.last_prompt == "hello"
        assert refreshes
        assert next_ms == c._settings.poll_interval_seconds * 1000

    def test_failing_hop_still_schedules_next_tick(self, tmp_path):
        c, entry, refreshes = _controller(tmp_path)

        def boom():
            raise RuntimeError("discovery bug")

        next_ms = _with(_patches(cwd=str(tmp_path), discover_sessions=boom), lambda: _run_tick(c))

        assert next_ms == c._settings.poll_interval_seconds * 1000
        assert entry.git_status == GitStatus.CLEAN
        assert not refreshes

    @pytest.mark.parametrize(
        "name,exc",
        [
            ("poll_session_states", RuntimeError("otel bug")),
            ("poll_last_prompts", RuntimeError("loki bug")),
            # Not an Exception: must still end the tick, not leave _poll re-arming
            ("poll_session_states", SystemExit(1)),
        ],
    )
    def test_failure_in_later_hop_ends_tick(self, tmp_path, name, exc):
        c, _entry, _refreshes = _controller(tmp_path)

        def boom(**_kwargs):
            raise exc

        next_ms = _with(_patches(cwd=str(tmp_path), **{name: boom}), lambda: _run_tick(c))

        assert next_ms == c._settings.poll_interval_seconds * 1000
        assert c._tick_in_flight is False

