class TestRenderDeferredDuringTick:
    def test_render_requested_mid_tick_runs_once_at_end(self):
        c, renders = _render_controller()

        c._tick_in_flight = True
        c._refresh_ui()  # e.g. a click between hops
        assert c._root.timers == [] and renders == []

        c._end_tick()
        assert c._tick_in_flight is False
        debounced = [fn for ms, fn in c._root.timers if ms == controller_mod._DEBOUNCE_MS]
        assert len(debounced) == 1

